const body = $input.all()[0].json.body;
const entry = body?.entry?.[0]?.messaging?.[0];
const text = entry?.message?.text;
const senderId = entry?.sender?.id;
const postback = entry?.postback?.payload;

if (
  body?.object === 'page' &&
  senderId
) {
  // Handle "Get Started" text
  if (text && text.trim().toLowerCase() === 'get started') {
    return [{ json: { type: 'text', text: 'get started', senderId } }];
  }
  // Handle postback button like "Yes, I agree"
  if (postback) {
    return [{ json: { type: 'postback', postback, senderId } }];
  }
  // Ignore other messages (optional)
  return [];
} else {
  return [{ json: { error: 'Invalid payload or missing sender' } }];
}

